// Builds an LS shadowing video from sentences cut out of the LS's own recordings.
// Each sentence: listen and read → your turn (pause) → listen again, no text → your turn (pause).
// Usage: node tools/shadowing-video/build.js tools/shadowing-video/<ls>.json [workdir]
// Needs ffmpeg and Playwright (Chromium). Nothing is generated by a paid service.
const fs = require('fs');
const path = require('path');
const os = require('os');
const { execFileSync } = require('child_process');
const { chromium } = require('playwright');

const ROOT = path.resolve(__dirname, '../..');
const spec = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const work = process.argv[3] || fs.mkdtempSync(path.join(os.tmpdir(), 'shadow-'));
fs.mkdirSync(work, { recursive: true });
const T = spec.theme;
const W = 1280, H = 720, FPS = 30;
const LEAD = 0.5, TAIL = 0.5;                      // silence around each playback
const BAR = { x: 290, y: 612, w: 700, h: 14 };      // timer bar during the pauses

const ff = (args) => execFileSync('ffmpeg', ['-v', 'error', '-y', ...args]);
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
const pretty = (s) => esc(s).replace(/'/g, '’');

const ICON = {
  ear: '<path d="M22 84V70a46 46 0 0 1 92 0v14" fill="none" stroke="currentColor" stroke-width="10" stroke-linecap="round"/><rect x="16" y="76" width="28" height="44" rx="10" fill="currentColor"/><rect x="92" y="76" width="28" height="44" rx="10" fill="currentColor"/>',
  mic: '<rect x="50" y="18" width="36" height="66" rx="18" fill="currentColor"/><path d="M34 66c0 20 15 34 34 34s34-14 34-34M68 100v22M50 124h36" fill="none" stroke="currentColor" stroke-width="9" stroke-linecap="round"/>',
};

function page(body) {
  return `<!doctype html><html><head><meta charset="utf-8"><style>
  *{box-sizing:border-box;margin:0}
  body{width:${W}px;height:${H}px;font-family:Inter,sans-serif;color:${T.ink};overflow:hidden;
    background:radial-gradient(circle at 88% 12%,${T.soft} 0,transparent 32%),linear-gradient(135deg,${T.bg1},${T.bg2});position:relative}
  .top{position:absolute;top:36px;left:56px;right:56px;display:flex;justify-content:space-between;align-items:center}
  .brand{display:flex;align-items:center;gap:14px;font-weight:700;font-size:21px;color:${T.title}}
  .logo{width:36px;height:36px;border-radius:9px;background:${T.accent};display:grid;place-items:center}
  .site{font-size:16px;font-weight:600;color:${T.muted}}
  .steps{position:absolute;top:104px;left:0;right:0;display:flex;justify-content:center;gap:10px}
  .st{padding:7px 16px;border-radius:999px;font-size:16px;font-weight:600;color:${T.muted};background:#fff;border:1.5px solid ${T.soft}}
  .st.on{background:${T.accent};border-color:${T.accent};color:#fff}
  .card{position:absolute;left:110px;right:110px;top:164px;height:400px;background:#fff;border-radius:28px;
    box-shadow:0 18px 50px rgba(30,50,90,.10);border:1px solid ${T.soft};display:flex;flex-direction:column;align-items:center;justify-content:center;padding:30px 60px;text-align:center}
  .who{font-size:18px;font-weight:700;color:${T.accent};letter-spacing:.02em;margin-bottom:18px;text-transform:uppercase}
  .say{font-weight:800;line-height:1.18;letter-spacing:-.01em}
  .dim{color:#9aa6b8}
  .icon{width:132px;height:132px;color:${T.accent};margin-bottom:20px}
  .big{font-size:44px;font-weight:800;color:${T.title}}
  .hint{font-size:22px;font-weight:500;color:${T.muted};margin-top:12px}
  .track{position:absolute;left:${BAR.x}px;top:${BAR.y}px;width:${BAR.w}px;height:${BAR.h}px;border-radius:3px;background:${T.soft}}
  .count{position:absolute;bottom:34px;left:0;right:0;text-align:center;font-size:17px;font-weight:600;color:${T.muted}}
  ol{font-size:27px;font-weight:600;line-height:1.75;text-align:left;color:${T.ink};padding-left:36px}
  ol b{color:${T.accent}}
  </style></head><body>
  <div class="top"><div class="brand"><span class="logo"><svg width="20" height="20" viewBox="0 0 20 20"><path d="M6 4l10 6-10 6z" fill="#fff"/></svg></span>Shadowing · ${esc(spec.ls)}</div>
  <div class="site">English Lab · ${esc(spec.course)}</div></div>${body}</body></html>`;
}

const STEPS = ['1 Listen and read', '2 Repeat', '3 Listen', '4 Repeat'];
const steps = (on) => `<div class="steps">${STEPS.map((s, i) => `<span class="st${i === on ? ' on' : ''}">${s}</span>`).join('')}</div>`;
const size = (t) => (t.length > 60 ? 46 : t.length > 40 ? 52 : 60);

function slides() {
  const n = spec.items.length, out = [];
  out.push(['intro', page(`<div class="card" style="top:120px;height:470px">
    <div class="big" style="margin-bottom:26px">Shadowing: say it like them!</div>
    <ol><li><b>Listen</b> and read the sentence.</li><li><b>Your turn:</b> say it out loud, same speed and rhythm.</li>
    <li><b>Listen again</b>, this time with no text.</li><li><b>Your turn again.</b> The video waits for you.</li></ol></div>
    <div class="count">${n} sentences · about ${Math.round(totalSecs() / 60)} minutes</div>`)]);
  spec.items.forEach((it, i) => {
    const sz = size(it.text), cnt = `<div class="count">Sentence ${i + 1} of ${n}</div>`;
    const who = `<div class="who">${esc(it.speaker)}</div>`;
    out.push([`s${i}a`, page(steps(0) + `<div class="card">${who}<div class="say" style="font-size:${sz}px">${pretty(it.text)}</div></div>` + cnt)]);
    out.push([`s${i}b`, page(steps(1) + `<div class="card"><svg class="icon" style="width:96px;height:96px;margin-bottom:14px" viewBox="0 0 136 136">${ICON.mic}</svg>
      <div class="big">Your turn: say it!</div><div class="say dim" style="font-size:${Math.round(sz * 0.62)}px;margin-top:22px">${pretty(it.text)}</div></div><div class="track"></div>` + cnt)]);
    out.push([`s${i}c`, page(steps(2) + `<div class="card"><svg class="icon" viewBox="0 0 136 136">${ICON.ear}</svg>
      <div class="big">Listen again</div><div class="hint">No text this time.</div></div>` + cnt)]);
    out.push([`s${i}d`, page(steps(3) + `<div class="card"><svg class="icon" viewBox="0 0 136 136">${ICON.mic}</svg>
      <div class="big">Your turn: say it again!</div><div class="hint">From memory, same speed and rhythm.</div></div><div class="track"></div>` + cnt)]);
  });
  out.push(['outro', page(`<div class="card"><div class="big">Well done!</div><div class="hint">Play it again tomorrow: it gets easier every time.</div></div>`)]);
  return out;
}

const clipLen = (it) => it.end - it.start;
function totalSecs() {
  return 8 + 4 + spec.items.reduce((s, it) => s + 2 * (LEAD + clipLen(it) + TAIL) + 2 * it.pause, 0);
}

(async () => {
  const browser = await chromium.launch();
  const pg = await browser.newPage({ viewport: { width: W, height: H } });
  for (const [id, html] of slides()) {
    await pg.setContent(html, { waitUntil: 'load' });
    await pg.evaluate(() => document.fonts.ready);
    await pg.screenshot({ path: path.join(work, id + '.png') });
  }
  await browser.close();

  const AF = ['-ar', '44100', '-ac', '1'];
  const V = ['-c:v', 'libx264', '-preset', 'medium', '-tune', 'stillimage', '-crf', '22', '-pix_fmt', 'yuv420p', '-r', String(FPS)];
  const A = ['-c:a', 'aac', '-b:a', '96k', ...AF];
  // A soft two-note chime that tells students it is their turn.
  const chime = path.join(work, 'chime.wav');
  ff(['-f', 'lavfi', '-i', 'sine=f=880:d=0.14', '-f', 'lavfi', '-i', 'sine=f=1320:d=0.22', '-filter_complex',
    '[0]afade=t=out:st=0.08:d=0.06[a];[1]afade=t=out:st=0.08:d=0.14[b];[a][b]concat=n=2:v=0:a=1,volume=0.25', ...AF, chime]);
  const segs = [];
  const still = (img, dur, audioArgs, filt, name) => {
    const f = path.join(work, name + '.mp4');
    ff(['-loop', '1', '-framerate', String(FPS), '-t', dur.toFixed(3), '-i', path.join(work, img + '.png'), ...audioArgs,
      ...(filt ? ['-filter_complex', filt] : []), '-t', dur.toFixed(3), ...V, ...A, '-shortest', f]);
    segs.push(f);
  };
  const silence = (d) => ['-f', 'lavfi', '-t', d.toFixed(3), '-i', `anullsrc=r=44100:cl=mono`];
  still('intro', 8, silence(8), null, 'intro');
  spec.items.forEach((it, i) => {
    const clip = path.join(work, `c${i}.wav`), d = clipLen(it);
    ff(['-ss', String(it.start), '-to', String(it.end), '-i', path.join(ROOT, spec.folder, it.src), '-af',
      `afade=t=in:d=0.03,afade=t=out:st=${(d - 0.06).toFixed(3)}:d=0.06,adelay=${LEAD * 1000},apad=pad_dur=${TAIL}`, ...AF, clip]);
    const play = LEAD + d + TAIL, P = it.pause;
    // The timer bar fills the track during the pause; the strip left of the track is put back on top.
    const bar = `[0:v]split[bg][m];[m]crop=${BAR.x}:${BAR.h}:0:${BAR.y}[left];color=c=${T.accent}:s=${BAR.w}x${BAR.h}:r=${FPS}[fill];` +
      `[bg][fill]overlay=x='${BAR.x - BAR.w}+${BAR.w}*t/${P}':y=${BAR.y}:shortest=1[v1];[v1][left]overlay=0:${BAR.y}`;
    const turn = ['-i', chime, '-af', `apad=whole_dur=${P}`];
    still(`s${i}a`, play, ['-i', clip], null, `s${i}a`);
    still(`s${i}b`, P, turn, bar, `s${i}b`);
    still(`s${i}c`, play, ['-i', clip], null, `s${i}c`);
    still(`s${i}d`, P, turn, bar, `s${i}d`);
  });
  still('outro', 4, silence(4), null, 'outro');
  const list = path.join(work, 'list.txt');
  fs.writeFileSync(list, segs.map((f) => `file '${f}'`).join('\n'));
  const out = path.join(ROOT, spec.folder, spec.out);
  ff(['-f', 'concat', '-safe', '0', '-i', list, '-c', 'copy', '-movflags', '+faststart', out]);
  // Poster for the page: the intro slide.
  ff(['-i', path.join(work, 'intro.png'), '-q:v', '3', out.replace(/\.mp4$/, '-poster.jpg')]);
  console.log(out, totalSecs().toFixed(1) + ' s');
})();
